package Responder;
use strict;
use warnings;

# Build the raw HTTP response headers for a redirect to $location.
sub redirect_headers {
    my ($location) = @_;
    $location =~ s/[\r\n]//g;
    return "HTTP/1.1 302 Found\r\nLocation: $location\r\nContent-Length: 0\r\n\r\n";
}

1;

use strict;
use warnings;
use Test::More;
use Responder;

subtest builds_redirect => sub {
    like(Responder::redirect_headers('/home'), qr{^Location: /home\r$}m, 'location header');
};

done_testing;
